# --- odyssey:unpack ---
# Embedded gzip+tar of src/odyssey. Regenerated when this file is rebuilt.
ODYSSEY_B64 = ""


def unpack_odyssey() -> Path:
    """Extract Odyssey onto sys.path (Colab /content, Vast /workspace/pkg)."""
    import hashlib
    if Path("/content").is_dir():
        root = Path("/content")
    elif Path("/workspace").is_dir():
        root = Path("/workspace") / "pkg"
    else:
        root = Path.cwd() / "pkg"
    root.mkdir(parents=True, exist_ok=True)
    fingerprint = hashlib.sha256(ODYSSEY_B64.encode("ascii")).hexdigest()
    marker = root / ".odyssey_b64.sha256"
    hit = (
        marker.is_file()
        and (root / "odyssey" / "__init__.py").is_file()
        and marker.read_text().strip() == fingerprint
    )
    if not hit:
        raw = base64.b64decode(ODYSSEY_B64)
        with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tf:
            try:
                tf.extractall(root, filter="data")
            except TypeError:
                tf.extractall(root)
        marker.write_text(fingerprint)
        for name in list(sys.modules):
            if name == "odyssey" or name.startswith("odyssey."):
                del sys.modules[name]
        importlib.invalidate_caches()
        print("Unpacked Odyssey to", root / "odyssey")
    else:
        print("Cached Odyssey at", root / "odyssey")
    root_s = str(root)
    sys.path = [p for p in sys.path if p != root_s]
    sys.path.insert(0, root_s)
    return root


unpack_odyssey()
# --- odyssey:unpack-end ---

