def parse_dataset_yaml(text: str) -> dict[str, str]:
    """Parse a tiny `key: value` YAML blob. No PyYAML."""
    out: dict[str, str] = {}
    for raw in text.splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line or ":" not in line:
            continue
        key, value = line.split(":", 1)
        key, value = key.strip(), value.strip().strip("'\"")
        if key:
            out[key] = value
    missing = [k for k in DATASET_YAML_KEYS if k not in out or not out[k]]
    if missing:
        raise ValueError(f"DATASET_YAML missing keys: {missing}")
    return out


def parse_dataset_paths(text: str) -> dict[str, Path]:
    return {key: Path(value) for key, value in parse_dataset_yaml(text).items()}


def find_cache_dir(paths: dict[str, Path]) -> Path:
    slot_cache = paths["slot_cache"]
    if (slot_cache / "cache.npy").is_file():
        return slot_cache
    matches = sorted(paths["root"].glob("slot_cache_rad_*/cache.npy"))
    if matches:
        return matches[0].parent
    raise FileNotFoundError(
        f"Rad cache not found. Expected {slot_cache / 'cache.npy'} "
        f"or {paths['root'] / 'slot_cache_rad_*' / 'cache.npy'}."
    )


LABEL_FILENAMES = (
    "labels.csv",
    "llm_labels_v4_blend.csv",
    "llm_labels_v2.csv",
    "llm_labels_full.csv",
)


def find_labels_path(paths: dict[str, Path], cache_dir: Path) -> Path:
    folders = (paths["targets"], cache_dir, cache_dir.parent, paths["root"])
    candidates = [folder / name for folder in folders for name in LABEL_FILENAMES]
    for path in candidates:
        if path.is_file():
            return path
    tried = [str(p) for p in candidates]
    raise FileNotFoundError(f"Label CSV not found. Tried: {tried}")


def find_rad_weights(paths: dict[str, Path]) -> Path:
    env = os.environ.get("RSNA_RAD_WEIGHT_PATH", "").strip()
    candidates: list[Path] = []
    if env:
        candidates.append(Path(env))
    models = paths["models"]
    candidates.append(models / "ResNet50.pt")
    if models.is_dir():
        candidates.extend(sorted(models.rglob("ResNet50.pt")))
    candidates.append(paths["root"] / "ResNet50.pt")
    seen: set[Path] = set()
    for path in candidates:
        resolved = path.resolve() if path.exists() else path
        if resolved in seen:
            continue
        seen.add(resolved)
        if path.is_file():
            return path
    raise FileNotFoundError(
        "RadImageNet ResNet50.pt not found. Place it under models or set RSNA_RAD_WEIGHT_PATH. "
        f"Tried: {[str(p) for p in candidates[:4]]}"
    )


def load_preprocess_meta(cache_dir: Path, root: Path) -> dict:
    for path in (
        cache_dir / "preprocess_meta.json",
        cache_dir.parent / "preprocess_meta.json",
        root / "preprocess_meta.json",
    ):
        if path.is_file():
            return json.loads(path.read_text(encoding="utf-8"))
    return {}


