@dataclass
class SlotCache:
    study_ids: list[str]
    cache: np.ndarray
    mask: np.ndarray
    _id_to_idx: dict[str, int] = field(init=False, repr=False)

    def __post_init__(self) -> None:
        self._id_to_idx = {sid: i for i, sid in enumerate(self.study_ids)}

    def __len__(self) -> int:
        return len(self.study_ids)

    def index_of(self, study_id: str) -> int:
        return self._id_to_idx[study_id]


def load_slot_cache(out_dir: Path) -> SlotCache:
    cache = np.load(out_dir / "cache.npy", mmap_mode="r")
    mask = np.load(out_dir / "mask.npy")
    ids_path = out_dir / "study_ids.txt"
    if not ids_path.is_file():
        raise FileNotFoundError(f"Missing study_ids.txt in {out_dir}")
    study_ids = [line.strip() for line in ids_path.read_text(encoding="utf-8").splitlines() if line.strip()]
    if len(study_ids) != cache.shape[0]:
        raise ValueError(
            f"study_ids ({len(study_ids)}) does not match cache N ({cache.shape[0]}) in {out_dir}"
        )
    return SlotCache(study_ids=study_ids, cache=cache, mask=mask)


def apply_mild_slot_augment(imgs: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
    """Whole-bag affine + intensity. imgs: uint8 [S, C, H, W]."""
    if imgs.numel() == 0:
        return imgs
    s, c, h, w = imgs.shape
    x = imgs.float()
    ang = math.radians((torch.rand(1).item() - 0.5) * 2 * MILD_ROT_DEG)
    sc = 1.0 + (torch.rand(1).item() - 0.5) * 2 * MILD_SCALE
    tx = (torch.rand(1).item() - 0.5) * 2 * MILD_SHIFT
    ty = (torch.rand(1).item() - 0.5) * 2 * MILD_SHIFT
    cos, sin = math.cos(ang) / sc, math.sin(ang) / sc
    theta = torch.tensor([[cos, -sin, tx], [sin, cos, ty]], dtype=torch.float32)
    theta = theta.unsqueeze(0).repeat(s, 1, 1)
    grid = F.affine_grid(theta, (s, c, h, w), align_corners=False)
    x = F.grid_sample(x, grid, mode="bilinear", padding_mode="zeros", align_corners=False)
    scale_i = 1.0 + (torch.rand(1).item() - 0.5) * 2 * MILD_INTENSITY
    x = (x * scale_i).clamp(0, 255)
    out = x.round().to(imgs.dtype)
    for i in range(s):
        if float(mask[i]) < 0.5:
            out[i] = imgs[i]
    return out


class KneeSlotDataset(Dataset):
    """Study-level bag: (imgs, mask, targets, confs, study_id). imgs uint8 [S, C, H, W]."""

    def __init__(
        self,
        df: pd.DataFrame,
        slot_cache: SlotCache,
        *,
        augment: bool = False,
    ) -> None:
        self.df = df.reset_index(drop=True)
        self.slot_cache = slot_cache
        self.augment = augment
        self.target_columns = [c for c in TARGET_COLUMNS if c in self.df.columns] or list(TARGET_COLUMNS)

    def __len__(self) -> int:
        return len(self.df)

    def _labels(self, row: pd.Series) -> tuple[torch.Tensor, torch.Tensor]:
        targets, confs = [], []
        for col in self.target_columns:
            val = row[col] if col in row.index else float("nan")
            conf_col = f"{col}__conf"
            conf = row[conf_col] if conf_col in row.index else 1.0
            targets.append(float("nan") if pd.isna(val) else float(val))
            confs.append(1.0 if pd.isna(conf) else float(conf))
        return (
            torch.tensor(targets, dtype=torch.float32),
            torch.tensor(confs, dtype=torch.float32),
        )

    def __getitem__(self, idx: int):
        row = self.df.iloc[idx]
        study_id = str(row[STUDY_ID_COLUMN])
        cache_idx = self.slot_cache.index_of(study_id)
        imgs = torch.from_numpy(np.asarray(self.slot_cache.cache[cache_idx]).copy())
        mask = torch.from_numpy(np.asarray(self.slot_cache.mask[cache_idx]).copy())
        targets, confs = self._labels(row)
        if self.augment:
            imgs = apply_mild_slot_augment(imgs, mask)
        return imgs, mask, targets, confs, study_id


def collate_slots(batch):
    imgs, masks, targets, confs, study_ids = zip(*batch)
    return (
        torch.stack(imgs, dim=0),
        torch.stack(masks, dim=0),
        torch.stack(targets, dim=0),
        torch.stack(confs, dim=0),
        list(study_ids),
    )


def worker_init_fn(worker_id: int) -> None:
    seed = torch.initial_seed() % (2**32)
    np.random.seed(seed + worker_id)


def set_seed(seed: int) -> None:
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    if torch.cuda.is_available():
        torch.cuda.manual_seed_all(seed)


def configure_cuda_speed() -> None:
    torch.set_float32_matmul_precision("high")
    if not torch.cuda.is_available():
        return
    torch.backends.cuda.matmul.allow_tf32 = True
    torch.backends.cudnn.allow_tf32 = True
    torch.backends.cudnn.benchmark = True
    torch.backends.cudnn.deterministic = False


def macro_roc_auc(y_true: np.ndarray, y_pred: np.ndarray) -> float:
    y_true = np.asarray(y_true, dtype=np.float64)
    y_pred = np.asarray(y_pred, dtype=np.float64)
    scores: list[float] = []
    for c in range(y_true.shape[1]):
        mask = ~np.isnan(y_true[:, c])
        if mask.sum() == 0:
            continue
        yt, yp = y_true[mask, c], y_pred[mask, c]
        if len(np.unique(yt)) < 2:
            continue
        scores.append(float(roc_auc_score(yt, yp)))
    return float("nan") if not scores else float(np.mean(scores))


