def _normalize_rad_state(state: dict) -> dict:
    out = {}
    for key, value in state.items():
        if key.endswith("num_batches_tracked"):
            continue
        out[key.removeprefix("backbone.") if key.startswith("backbone.") else key] = value
    return out


class RadEncoder(nn.Module):
    """Frozen RadImageNet ResNet50; GAP token dim 2048. Norm: x/127.5 - 1."""

    def __init__(self, weights_path: Path) -> None:
        super().__init__()
        self.backbone = nn.Sequential(*list(resnet50(weights=None).children())[:-2])
        try:
            raw = torch.load(weights_path, map_location="cpu", weights_only=True)
        except TypeError:
            raw = torch.load(weights_path, map_location="cpu")
        if isinstance(raw, dict) and "state_dict" in raw:
            raw = raw["state_dict"]
        if not isinstance(raw, dict):
            raise ValueError(f"Unexpected RadImageNet weight format in {weights_path}")
        self.backbone.load_state_dict(_normalize_rad_state(raw), strict=True)
        self.token_dim = TOKEN_DIM
        for param in self.parameters():
            param.requires_grad_(False)

    def train(self, mode: bool = True):  # noqa: ARG002
        return super().train(False)

    def forward(self, image: torch.Tensor) -> torch.Tensor:
        x = image.float().div(127.5).sub(1.0)
        with torch.no_grad():
            return self.backbone(x).mean(dim=(2, 3))


class RadHead(nn.Module):
    """Plane/position MHA over slice tokens + 4-way fuse → 12 logits."""

    def __init__(self, n_slot: int, n_slice: int, n_out: int = NUM_CLASSES) -> None:
        super().__init__()
        self.n_slot = n_slot
        self.n_slice = n_slice
        self.project = nn.Sequential(nn.LayerNorm(TOKEN_DIM), nn.Linear(TOKEN_DIM, HEAD_DIM), nn.GELU())
        self.plane = nn.Parameter(torch.randn(n_slot, HEAD_DIM) * 0.01)
        self.position = nn.Parameter(torch.randn(n_slice, HEAD_DIM) * 0.01)
        self.query = nn.Parameter(torch.randn(n_out, HEAD_DIM) * 0.02)
        self.attn = nn.MultiheadAttention(HEAD_DIM, 8, dropout=0.10, batch_first=True)
        self.fuse = nn.Sequential(
            nn.LayerNorm(HEAD_DIM * 4),
            nn.Linear(HEAD_DIM * 4, HEAD_DIM),
            nn.GELU(),
            nn.Dropout(0.15),
        )
        self.weight = nn.Parameter(torch.randn(n_out, HEAD_DIM) * 0.02)
        self.bias = nn.Parameter(torch.zeros(n_out))

    def forward(self, feature: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        token = self.project(feature.float())
        token = token.view(len(token), self.n_slot, self.n_slice, -1)
        token = token + self.plane[None, :, None] + self.position[None, None]
        token = token.flatten(1, 2)
        key_padding = mask <= 0
        all_empty = key_padding.all(1)
        if all_empty.any():
            key_padding = key_padding.clone()
            key_padding[all_empty, 0] = False
        query = self.query.unsqueeze(0).expand(len(token), -1, -1)
        attended = query + self.attn(query, token, token, key_padding_mask=key_padding, need_weights=False)[0]
        denom = mask.sum(1, keepdim=True).clamp_min(1).unsqueeze(-1)
        mean = (token * mask.unsqueeze(-1)).sum(1, keepdim=True) / denom
        mean = mean.expand(-1, len(self.query), -1)
        fused = self.fuse(torch.cat([attended, mean, torch.abs(attended - mean), attended * mean], dim=-1))
        return (fused * self.weight.unsqueeze(0)).sum(-1) + self.bias


class RadModel(nn.Module):
    """Encode every slice independently, then fuse with RadHead."""

    def __init__(self, n_slot: int, n_slice: int, weights_path: Path) -> None:
        super().__init__()
        self.encoder = RadEncoder(weights_path)
        self.head = RadHead(n_slot=n_slot, n_slice=n_slice)

    def forward(self, imgs: torch.Tensor, mask: torch.Tensor, img_size: int | None = None) -> torch.Tensor:
        b, s, c, h, w = imgs.shape
        flat = imgs.reshape(b * s * c, h, w)
        if img_size is not None and img_size != h:
            flat = F.interpolate(
                flat.unsqueeze(1).float(),
                size=(img_size, img_size),
                mode="bilinear",
                align_corners=False,
            ).squeeze(1)
        x = flat.float().unsqueeze(1).expand(-1, 3, -1, -1).contiguous()
        feats = self.encoder(x).view(b, s * c, -1)
        token_mask = mask.unsqueeze(-1).expand(-1, -1, c).reshape(b, s * c)
        return self.head(feats, token_mask)


class LitRad(L.LightningModule):
    """BCE + pairwise rank loss; frozen backbone; OneCycle on the head."""

    def __init__(self, model: nn.Module, img_size: int) -> None:
        super().__init__()
        self.model = model
        self.img_size = img_size
        self.lr_head = LR_HEAD
        self.weight_decay = WEIGHT_DECAY
        self.rank_loss_w = RANK_LOSS_W
        self._val_probs: list[np.ndarray] = []
        self._val_targets: list[np.ndarray] = []

    def forward(self, imgs: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
        return self.model(imgs, mask, self.img_size)

    def _bce(self, logits: torch.Tensor, targets: torch.Tensor, confs: torch.Tensor) -> torch.Tensor:
        valid = ~torch.isnan(targets)
        if valid.sum() == 0:
            return logits.sum() * 0.0
        weight = confs.clamp(min=0.05) * valid.float()
        loss = F.binary_cross_entropy_with_logits(logits, targets.nan_to_num(0.0), reduction="none")
        return (loss * weight).sum() / weight.sum().clamp(min=1.0)

    def _rank(self, logits: torch.Tensor, targets: torch.Tensor, weights: torch.Tensor) -> torch.Tensor:
        if self.rank_loss_w <= 0:
            return logits.sum() * 0.0
        parts = []
        usable = weights > 0
        for j in range(logits.shape[1]):
            pos = logits[(targets[:, j] > RANK_POS) & usable[:, j], j]
            neg = logits[(targets[:, j] < RANK_NEG) & usable[:, j], j]
            if len(pos) and len(neg):
                parts.append(F.softplus(-(pos[:, None] - neg[None, :])).mean())
        if not parts:
            return logits.new_tensor(0.0)
        return torch.stack(parts).mean()

    def _step(self, batch, *, stage: str) -> torch.Tensor:
        imgs, mask, targets, confs, _ids = batch
        logits = self(imgs, mask)
        bce = self._bce(logits, targets, confs)
        weight = confs.clamp(min=0.05) * (~torch.isnan(targets)).float()
        loss = bce + self.rank_loss_w * self._rank(logits, targets, weight)
        self.log(f"{stage}_loss", loss, on_step=False, on_epoch=True, batch_size=int(imgs.size(0)))
        return loss

    def training_step(self, batch, batch_idx) -> torch.Tensor:
        return self._step(batch, stage="train")

    def on_validation_epoch_start(self) -> None:
        self._val_probs.clear()
        self._val_targets.clear()

    def validation_step(self, batch, batch_idx) -> torch.Tensor:
        imgs, mask, targets, confs, _ids = batch
        logits = self(imgs, mask)
        bce = self._bce(logits, targets, confs)
        weight = confs.clamp(min=0.05) * (~torch.isnan(targets)).float()
        loss = bce + self.rank_loss_w * self._rank(logits, targets, weight)
        self.log("val_loss", loss, on_step=False, on_epoch=True, batch_size=int(imgs.size(0)))
        probs = torch.sigmoid(logits).detach().cpu().numpy()
        y = targets.detach().cpu().numpy()
        y_bin = np.where(np.isnan(y), np.nan, (y >= 0.5).astype(np.float64))
        self._val_probs.append(probs)
        self._val_targets.append(y_bin)
        return loss

    def on_validation_epoch_end(self) -> None:
        if not self._val_probs:
            return
        y_pred = np.concatenate(self._val_probs, axis=0)
        y_true = np.concatenate(self._val_targets, axis=0)
        auc = macro_roc_auc(y_true, y_pred)
        self.log("val_macro_auc", auc, on_epoch=True)
        if self.trainer.sanity_checking:
            return
        metrics = self.trainer.callback_metrics
        train = metrics.get("train_loss")
        val = metrics.get("val_loss")
        train_s = f"{float(train):.4f}" if train is not None else "-"
        val_s = f"{float(val):.4f}" if val is not None else "-"
        auc_s = "nan" if auc != auc else f"{float(auc):.4f}"
        epoch = int(self.current_epoch) + 1
        total = int(self.trainer.max_epochs or 0)
        print(f"epoch {epoch}/{total}  train {train_s}  val {val_s}  auc {auc_s}", flush=True)

    def configure_optimizers(self):
        params = [p for p in self.model.head.parameters() if p.requires_grad]
        optimizer = torch.optim.AdamW(params, lr=self.lr_head, weight_decay=self.weight_decay)
        try:
            total_steps = int(self.trainer.estimated_stepping_batches)
        except (TypeError, OverflowError, ValueError):
            total_steps = 0
        if total_steps <= 0:
            total_steps = max(1, int(self.trainer.max_epochs or 1))
        scheduler = torch.optim.lr_scheduler.OneCycleLR(
            optimizer,
            max_lr=self.lr_head,
            total_steps=total_steps,
            pct_start=0.15,
        )
        return {"optimizer": optimizer, "lr_scheduler": {"scheduler": scheduler, "interval": "step"}}


# ---------------------------------------------------------------------------
# Train
# ---------------------------------------------------------------------------


def build_loaders(
    pool_df: pd.DataFrame,
    slot_cache: SlotCache,
    *,
    n_slot: int,
    n_slice: int,
) -> tuple[DataLoader, DataLoader, int, int]:
    cached_ids = set(map(str, slot_cache.study_ids))
    pool_df = pool_df[pool_df[STUDY_ID_COLUMN].astype(str).isin(cached_ids)].reset_index(drop=True)
    if len(pool_df) == 0:
        raise RuntimeError("No overlap between labels.csv and slot cache study IDs.")
    if MAX_STUDIES is not None:
        keep = (
            pool_df[STUDY_ID_COLUMN]
            .astype(str)
            .drop_duplicates()
            .sample(n=min(int(MAX_STUDIES), pool_df[STUDY_ID_COLUMN].nunique()), random_state=SEED)
        )
        pool_df = pool_df[pool_df[STUDY_ID_COLUMN].astype(str).isin(set(keep))].reset_index(drop=True)

    study_ids = pool_df[STUDY_ID_COLUMN].astype(str).unique()
    if len(study_ids) < 2:
        raise RuntimeError(f"Need at least 2 studies to split, got {len(study_ids)}.")
    train_studies, valid_studies = train_test_split(study_ids, test_size=0.2, random_state=SEED)

    train_df = pool_df[pool_df[STUDY_ID_COLUMN].astype(str).isin(train_studies)].reset_index(drop=True)
    valid_df = pool_df[pool_df[STUDY_ID_COLUMN].astype(str).isin(valid_studies)].reset_index(drop=True)
    train_ds = KneeSlotDataset(train_df, slot_cache, augment=AUGMENT)
    valid_ds = KneeSlotDataset(valid_df, slot_cache, augment=False)

    loader_kw: dict = dict(
        batch_size=BATCH_SIZE,
        num_workers=NUM_WORKERS,
        collate_fn=collate_slots,
        pin_memory=torch.cuda.is_available(),
        persistent_workers=NUM_WORKERS > 0,
    )
    if NUM_WORKERS > 0:
        loader_kw["worker_init_fn"] = worker_init_fn
        loader_kw["prefetch_factor"] = 2

    train_loader = DataLoader(
        train_ds,
        shuffle=True,
        drop_last=len(train_ds) >= BATCH_SIZE,
        **loader_kw,
    )
    valid_loader = DataLoader(valid_ds, shuffle=False, **loader_kw)
    return train_loader, valid_loader, len(train_ds), len(valid_ds)


def main() -> None:
    global LAYOUT, SEED

    paths = parse_dataset_paths(DATASET_YAML)
    cache_dir = find_cache_dir(paths)
    labels_path = find_labels_path(paths, cache_dir)
    weights_path = find_rad_weights(paths)
    out_dir = paths["output"]
    out_dir.mkdir(parents=True, exist_ok=True)

    meta = load_preprocess_meta(cache_dir, paths["root"])
    layout = str(meta.get("layout", LAYOUT))
    seed = int(meta.get("seed", SEED))
    LAYOUT, SEED = layout, seed
    n_slice = int(meta.get("n_slice", 8))
    n_slot = int(meta.get("n_slot", 3 if layout == "e10" else 4))

    set_seed(seed)
    configure_cuda_speed()

    pool_df = pd.read_csv(labels_path)
    pool_df[STUDY_ID_COLUMN] = pool_df[STUDY_ID_COLUMN].astype(str)
    slot_cache = load_slot_cache(cache_dir)
    n_slot = int(slot_cache.cache.shape[1])
    n_slice = int(slot_cache.cache.shape[2])
    train_loader, valid_loader, n_train, n_val = build_loaders(
        pool_df, slot_cache, n_slot=n_slot, n_slice=n_slice
    )

    gpu = torch.cuda.get_device_name(0) if torch.cuda.is_available() else "cpu"
    print(f"{gpu}  torch {torch.__version__}  {layout} {n_slot}x{n_slice}  seed {seed}")
    print(f"cache {cache_dir.name} {tuple(slot_cache.cache.shape)}  labels {labels_path.name} n={len(pool_df)}")
    print(f"train {n_train} / val {n_val}  epochs {MAX_EPOCHS}  batch {BATCH_SIZE}  out {out_dir}")

    model = RadModel(n_slot=n_slot, n_slice=n_slice, weights_path=weights_path)
    lit = LitRad(model, img_size=IMG_SIZE)
    ckpt_name = f"best_rad_{layout}_r{IMG_SIZE}"
    checkpoint = ModelCheckpoint(
        dirpath=str(out_dir),
        filename=ckpt_name,
        monitor="val_loss",
        mode="min",
        save_top_k=1,
        verbose=False,
    )
    trainer = L.Trainer(
        max_epochs=MAX_EPOCHS,
        accelerator="auto",
        devices=1,
        precision="16-mixed",
        accumulate_grad_batches=ACCUMULATE_GRAD_BATCHES,
        callbacks=[checkpoint],
        logger=False,
        enable_progress_bar=False,
        enable_model_summary=False,
        num_sanity_val_steps=0,
        log_every_n_steps=1000,
        benchmark=True,
    )
    trainer.fit(lit, train_loader, valid_loader)

    best = checkpoint.best_model_path or "(none)"
    print(f"best {best}")


if __name__ == "__main__":
    main()
